css:
:root {
  --paper: #f2f3ee;
  --paper-bright: #fbfbf7;
  --ink: #0d1a13;
  --ink-soft: #47544c;
  --line: #ccd2c7;
  --line-strong: #6f7b72;
  --green: #1c6b4b;
  --green-deep: #0d3d2b;
  --high: #dff25c;
  --dark: #0a1510;
  --cream: #f2f3ee;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  --wrap: 1240px;
  --pad: clamp(20px, 4vw, 48px);
}

*,
*::before,
*::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

section[id] { scroll-margin-top: 84px; }

body {
  margin: 0;
  overflow-x: clip;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3, p { margin: 0; }
ul, ol { margin: 0; padding: 0; list-style: none; }
a { color: inherit; text-decoration: none; }
svg { display: block; max-width: 100%; }

::selection {
  background: var(--high);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--green);
  outline-offset: 3px;
}

.wrap {
  width: 100%;
  max-width: var(--wrap);
  margin-inline: auto;
  padding-inline: var(--pad);
}

.skip-link {
  position: absolute;
  left: 16px;
  top: -64px;
  z-index: 100;
  padding: 10px 14px;
  border-radius: 6px;
  background: var(--ink);
  color: var(--paper);
  font-size: 14px;
  font-weight: 600;
  transition: top 0.2s ease;
}

.skip-link:focus { top: 12px; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(13, 26, 19, 0.09);
  background: rgba(242, 243, 238, 0.88);
  -webkit-backdrop-filter: saturate(1.4) blur(12px);
  backdrop-filter: saturate(1.4) blur(12px);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: 72px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 19px;
  font-weight: 650;
  letter-spacing: -0.03em;
}

.brand svg {
  width: 24px;
  height: 24px;
  flex: none;
}

.site-nav {
  display: flex;
  gap: 30px;
  margin-inline: auto;
  font-size: 14px;
  color: var(--ink-soft);
}

.site-nav a {
  position: relative;
  padding-block: 6px;
}

.site-nav a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--ink);
  transition: right 0.25s ease;
}

.site-nav a:hover::after { right: 0; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  font-size: 14px;
}

.header-demo {
  color: var(--ink-soft);
  transition: color 0.2s ease;
}

.header-demo:hover { color: var(--ink); }

.hero {
  position: relative;
  isolation: isolate;
  overflow: clip;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    rgba(13, 26, 19, 0.055) 0 1px,
    transparent 1px 48px
  );
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 16%, #000 70%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 16%, #000 70%, transparent);
}

.hero::after {
  content: "";
  position: absolute;
  top: 8%;
  right: -16%;
  z-index: 0;
  width: min(760px, 72vw);
  aspect-ratio: 1;
  pointer-events: none;
  background: radial-gradient(circle at center, rgba(223, 242, 92, 0.34), rgba(223, 242, 92, 0) 66%);
  filter: blur(12px);
}

.hero-inner {
  position: relative;
  z-index: 1;
  padding-top: clamp(48px, 6vw, 84px);
  padding-bottom: clamp(64px, 8vw, 112px);
}

.kicker {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ink-soft);
}

.kicker::before {
  content: "";
  width: 26px;
  height: 1px;
  flex: none;
  background: currentColor;
}

h1 {
  margin-top: clamp(22px, 3vw, 38px);
  font-size: clamp(3rem, 7.2vw, 7rem);
  line-height: 0.95;
  font-weight: 600;
  letter-spacing: -0.06em;
}

.h1-accent {
  display: block;
  width: fit-content;
  padding-right: 0.08em;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.045em;
  background-image: linear-gradient(
    transparent 64%,
    var(--high) 64%,
    var(--high) 93%,
    transparent 93%
  );
  background-repeat: no-repeat;
  background-position: 0 0;
  background-size: 100% 100%;
}

.hero-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: clamp(24px, 3.4vw, 48px);
  align-items: start;
  margin-top: clamp(36px, 4.5vw, 56px);
}

.hero-copy {
  grid-column: 1 / span 5;
  padding-top: 6px;
}

.lede {
  max-width: 47ch;
  font-size: clamp(1.0625rem, 1.3vw, 1.1875rem);
  line-height: 1.6;
  color: var(--ink-soft);
  text-wrap: pretty;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px 22px;
  margin-top: 30px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: 9px;
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease,
    transform 0.2s ease;
}

.btn-primary {
  background: var(--ink);
  color: var(--paper-bright);
}

.btn-primary:hover {
  background: var(--green);
  transform: translateY(-1px);
}

.btn-secondary {
  border-color: var(--line-strong);
  background: transparent;
  color: var(--ink);
}

.btn-secondary:hover {
  border-color: var(--ink);
  background: rgba(13, 26, 19, 0.045);
}

.btn-small {
  min-height: 40px;
  padding: 0 16px;
  border-radius: 8px;
  font-size: 13px;
}

.hero-demo {
  position: relative;
  grid-column: 6 / span 7;
  margin-top: -4px;
  padding: 0 12px 26px 0;
}

.demo-offset {
  position: absolute;
  top: 14px;
  right: -6px;
  bottom: 12px;
  left: 14px;
  z-index: 0;
  border: 1px solid #c8cfc0;
  border-radius: 16px;
  background: #e5e9de;
}

.demo {
  position: relative;
  z-index: 1;
  overflow: hidden;
  border: 1px solid #c9cfc3;
  border-radius: 16px;
  background: var(--paper-bright);
  box-shadow: 0 30px 70px -38px rgba(13, 26, 19, 0.48);
}

.demo-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--line);
}

.demo-title {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 13.5px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.live-dot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 4px rgba(28, 107, 75, 0.12);
}

.demo-period {
  font-family: var(--mono);
  font-size: 12px;
  color: var(--ink-soft);
}

.demo-cols {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 20px;
  border-bottom: 1px solid var(--line);
  background: #f5f6f1;
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-soft);
}

.demo-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 13px 20px;
}

.demo-row + .demo-row { border-top: 1px solid var(--line); }

.row-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--green);
}

.row-icon svg {
  width: 15px;
  height: 15px;
}

.row-main { min-width: 0; }

.row-name {
  display: block;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.row-meta {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.4;
  color: var(--ink-soft);
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
}

.chip-ok {
  background: rgba(28, 107, 75, 0.085);
  color: var(--green);
}

.chip-flag {
  background: var(--high);
  color: var(--ink);
}

.demo-row-flag {
  position: relative;
  background: linear-gradient(90deg, rgba(223, 242, 92, 0.52), rgba(223, 242, 92, 0.16));
}

.demo-row-flag::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  background: var(--ink);
}

.demo-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 20px;
  background: #f4f5ef;
  font-size: 13px;
}

.foot-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.foot-label svg {
  width: 16px;
  height: 16px;
  flex: none;
  color: var(--green);
}

.foot-link {
  color: var(--green);
  font-weight: 600;
}

.stamp {
  position: absolute;
  right: 2px;
  bottom: -2px;
  z-index: 2;
  transform: rotate(-3deg);
  padding: 6px 9px;
  border: 1.5px solid var(--green-deep);
  border-radius: 5px;
  background: rgba(251, 251, 247, 0.92);
  box-shadow: 0 2px 0 rgba(13, 26, 19, 0.08);
  color: var(--green-deep);
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.features {
  border-top: 1px solid var(--line);
  padding-block: clamp(72px, 9vw, 120px);
}

.features .kicker { margin-bottom: 18px; }

.section-title {
  max-width: 16ch;
  font-size: clamp(2.1rem, 3.8vw, 3.5rem);
  line-height: 1.02;
  font-weight: 600;
  letter-spacing: -0.05em;
  text-wrap: balance;
}

.feature-list { margin-top: clamp(40px, 5vw, 64px); }

.feature {
  display: grid;
  grid-template-columns: 5fr 7fr;
  gap: clamp(24px, 4vw, 64px);
  padding-block: clamp(26px, 3vw, 38px);
  border-top: 1px solid var(--line);
}

.feature:first-child { border-top-color: var(--ink); }

.feature-list { border-bottom: 1px solid var(--line); }

.feature-title {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.f-icon {
  width: 30px;
  height: 30px;
  flex: none;
  margin-top: 2px;
  color: var(--green);
}

.feature h3 {
  font-size: clamp(1.3rem, 2vw, 1.65rem);
  line-height: 1.15;
  font-weight: 600;
  letter-spacing: -0.03em;
}

.feature p {
  max-width: 58ch;
  font-size: clamp(1rem, 1.15vw, 1.0625rem);
  line-height: 1.65;
  color: var(--ink-soft);
  text-wrap: pretty;
}

.how {
  position: relative;
  overflow: clip;
  background: var(--dark);
  color: var(--cream);
}

.how::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(to right, rgba(242, 243, 238, 0.055) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(242, 243, 238, 0.04) 1px, transparent 1px);
  background-size: 88px 88px;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 24%, #000 82%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 24%, #000 82%, transparent);
}

.how .wrap {
  position: relative;
  z-index: 1;
  padding-block: clamp(72px, 9vw, 120px);
}

.kicker-dark { color: rgba(242, 243, 238, 0.6); }
.kicker-dark::before { background: rgba(242, 243, 238, 0.38); }

.section-title-dark { color: var(--cream); }

.steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(24px, 4vw, 64px);
  margin-top: clamp(48px, 6vw, 72px);
}

.steps::before {
  content: "";
  position: absolute;
  top: 15px;
  left: 15px;
  right: 15px;
  height: 1px;
  background: rgba(242, 243, 238, 0.18);
}

.step {
  position: relative;
  padding-top: 56px;
}

.step-num {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--high);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}

.step h3 {
  font-size: clamp(1.15rem, 1.7vw, 1.4rem);
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.step p {
  max-width: 32ch;
  margin-top: 10px;
  font-size: 15px;
  line-height: 1.6;
  color: rgba(242, 243, 238, 0.64);
  text-wrap: pretty;
}

.closing {
  position: relative;
  overflow: clip;
  background: var(--high);
}

.closing::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(
    to right,
    rgba(13, 26, 19, 0.085) 0 1px,
    transparent 1px 80px
  );
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 28%, #000 74%, transparent);
  mask-image: linear-gradient(to bottom, transparent, #000 28%, #000 74%, transparent);
}

.closing .wrap {
  position: relative;
  z-index: 1;
}

.closing-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.7fr);
  gap: clamp(32px, 6vw, 80px);
  align-items: end;
  padding-block: clamp(72px, 10vw, 128px);
}

.closing .kicker { color: rgba(13, 26, 19, 0.64); }

.closing h2 {
  max-width: 14ch;
  margin-top: 16px;
  font-size: clamp(2.5rem, 5.4vw, 5rem);
  line-height: 0.98;
  font-weight: 600;
  letter-spacing: -0.055em;
  text-wrap: balance;
}

.closing-accent {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  letter-spacing: -0.02em;
}

.closing-actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  justify-self: end;
  width: 100%;
  max-width: 320px;
  padding-bottom: 6px;
}

.closing .btn-primary {
  background: var(--ink);
  color: var(--high);
}

.closing .btn-primary:hover {
  background: var(--green-deep);
  color: var(--cream);
}

.closing .btn-outline {
  border-color: rgba(13, 26, 19, 0.6);
  color: var(--ink);
}

.closing .btn-outline:hover {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--high);
}

.closing-note {
  margin-top: 6px;
  font-size: 13px;
  line-height: 1.5;
  color: rgba(13, 26, 19, 0.68);
  text-align: center;
}

.closing :focus-visible { outline-color: var(--ink); }
.how :focus-visible { outline-color: var(--high); }

.site-footer {
  background: var(--dark);
  color: rgba(242, 243, 238, 0.62);
}

.footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-block: 26px;
  font-size: 13px;
}

.brand-footer {
  color: var(--cream);
  font-size: 16px;
}

.brand-footer svg {
  width: 20px;
  height: 20px;
}

.copyright {
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.02em;
}

@media (prefers-reduced-motion: no-preference) {
  .hero .kicker,
  h1,
  .hero-copy,
  .hero-demo {
    animation: rise 0.8s cubic-bezier(0.22, 0.68, 0.22, 1) both;
  }

  .hero .kicker { animation-delay: 0.04s; }
  h1 { animation-delay: 0.1s; }
  .hero-copy { animation-delay: 0.2s; }
  .hero-demo { animation-delay: 0.28s; }

  .h1-accent {
    background-size: 0% 100%;
    animation: mark 1s 0.75s cubic-bezier(0.22, 0.68, 0.22, 1) forwards;
  }

  @keyframes rise {
    from { opacity: 0; transform: translateY(18px); }
    to { opacity: 1; transform: translateY(0); }
  }

  @keyframes mark {
    from { background-size: 0% 100%; }
    to { background-size: 100% 100%; }
  }
}

@media (max-width: 940px) {
  .hero-grid { grid-template-columns: minmax(0, 1fr); }
  .hero-copy,
  .hero-demo { grid-column: 1 / -1; }
  .hero-copy { max-width: 640px; }
  .hero-demo {
    max-width: 720px;
    margin-top: 26px;
    padding-right: 0;
  }
  .demo-offset { right: 0; }
}

@media (max-width: 820px) {
  .site-nav,
  .header-demo { display: none; }
  .header-inner { height: 62px; }
  .header-actions { margin-left: auto; }
}

@media (max-width: 760px) {
  .feature {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .steps {
    grid-template-columns: minmax(0, 1fr);
    gap: 34px;
    margin-top: 40px;
  }

  .steps::before {
    top: 15px;
    right: auto;
    bottom: 15px;
    left: 15px;
    width: 1px;
    height: auto;
  }

  .step {
    min-height: 30px;
    padding-top: 0;
    padding-left: 52px;
  }

  .step p { max-width: 44ch; }

  .closing-grid {
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
  }

  .closing-actions {
    justify-self: start;
    max-width: none;
    margin-top: 6px;
  }

  .closing-note { text-align: left; }

  .footer-inner {
    flex-wrap: wrap;
    gap: 10px 24px;
  }
}

@media (max-width: 520px) {
  .hero-actions {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }

  .hero-actions .btn { width: 100%; }

  .demo-row {
    grid-template-columns: 28px minmax(0, 1fr);
    row-gap: 7px;
  }

  .demo-row .chip {
    grid-column: 2;
    justify-self: start;
  }

  .demo-foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .stamp {
    right: 8px;
    bottom: 0;
  }

  .footer-inner {
    flex-direction: column;
    align-items: flex-start;
  }
}
